codeExample.bad:
/* A 1px outline in a color close to the button's own background
   color fails to meet the 2px minimum size and 3:1 contrast ratio */
.button {
  background-color: #2255aa;
}
.button:focus {
  outline: 1px solid #2a5cb0;
}

codeExample.good:
/* A 3px outline in a high-contrast color clearly exceeds the 2px
   minimum thickness and provides well over 3:1 contrast against the
   button's unfocused background */
.button {
  background-color: #2255aa;
}
.button:focus {
  outline: 3px solid #ffcc00;
  outline-offset: 2px;
}
